Here is the complete Python function `shortest_path` using Dijkstra's algorithm. 

It includes validation for negative edge weights (raising a `ValueError`) and correctly handles edge cases such as when the start and end nodes are the same or when no path exists.

```python
import heapq
from collections import defaultdict

def shortest_path(edges, start, end):
    """
    Finds the shortest path and its total distance between a start and end node
    in a directed, weighted graph using Dijkstra's algorithm.

    :param edges: List of tuples (from_node, to_node, weight)
    :param start: Starting node
    :param end: Target node
    :return: Tuple of (total_distance, [list_of_nodes]) or (None, None) if no path exists
    """
    # Check for negative weights
    for _, _, weight in edges:
        if weight < 0:
            raise ValueError("Negative edge weights are not allowed.")

    # Edge case: start and end are the same
    if start == end:
        return (0, [start])

    # Build the adjacency list
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))
        # Ensure nodes with no outgoing edges still exist in the graph dictionary
        if v not in graph:
            graph[v] = []

    # If start or end nodes aren't in the graph at all
    if start not in graph or end not in graph:
        return (None, None)

    # Priority queue stores: (current_distance, current_node, path_so_far)
    pq = [(0, start, [start])]

    # Track visited nodes to prevent redundant processing
    visited = set()

    while pq:
        current_distance, current_node, path = heapq.heappop(pq)

        # If we reached the destination, return the result
        if current_node == end:
            return (current_distance, path)

        if current_node in visited:
            continue
        visited.add(current_node)

        for neighbor, weight in graph[current_node]:
            if neighbor not in visited:
                heapq.heappush(pq, (current_distance + weight, neighbor, path + [neighbor]))

    # If the priority queue empties and we haven't returned, no route exists
    return (None, None)

# --- Example Usage ---
if __name__ == "__main__":
    edges = [("A", "B", 1), ("B", "C", 2), ("A", "C", 5)]
    print(shortest_path(edges, "A", "C"))  # Output: (3, ['A', 'B', 'C'])

    # Test same start and end
    print(shortest_path(edges, "A", "A"))  # Output: (0, ['A'])

    # Test non-existent route
    print(shortest_path(edges, "C", "A"))  # Output: (None, None)

    # Test negative weight exception
    try:
        shortest_path([("A", "B", -1)], "A", "B")
    except ValueError as e:
        print(e)  # Output: Negative edge weights are not allowed.
```

